const { AccountCreationUtils } = ChromeUtils.importESModule(
  "resource:///modules/accountcreation/AccountCreationUtils.sys.mjs"
);
const { AccountConfig } = ChromeUtils.importESModule(
  "resource:///modules/accountcreation/AccountConfig.sys.mjs"
);

const { InputSanitizer } = ChromeUtils.importESModule(
  "resource:///modules/accountcreation/InputSanitizer.sys.mjs"
);

const { OAuth2Providers } = ChromeUtils.importESModule(
  "resource:///modules/OAuth2Providers.sys.mjs"
);

const { gAccountSetupLogger, standardPorts, assert } = AccountCreationUtils;

import { AccountHubStep } from "./account-hub-step.mjs";
import "./account-hub-select.mjs"; // eslint-disable-line import/no-unassigned-import
import "./account-hub-input.mjs"; // eslint-disable-line import/no-unassigned-import

/**
 * Account Hub Email Incoming Form Template
 * Template ID: #accountHubEmailIncomingFormTemplate (from accountHubEmailIncomingFormTemplate.inc.xhtml)
 */
class EmailIncomingForm extends AccountHubStep {
  /**
   * The incoming server protocol.
   *
   * @type {HTMLInputElement}
   */
  #incomingProtocol;

  /**
   * The incoming server hostname.
   *
   * @type {HTMLInputElement}
   */
  #incomingHostname;

  /**
   * The incoming server port.
   *
   * @type {HTMLInputElement}
   */
  #incomingPort;

  /**
   * The incoming server connection security.
   *
   * @type {HTMLInputElement}
   */
  #incomingConnectionSecurity;

  /**
   * The incoming server authentication method.
   *
   * @type {HTMLInputElement}
   */
  #incomingAuthenticationMethod;

  /**
   * The incoming username.
   *
   * @type {HTMLInputElement}
   */
  #incomingUsername;

  /**
   * The EWS URL for an ews config.
   *
   * @type {HTMLInputElement}
   */
  #incomingExchangeUrl;

  /**
   * The current email incoming config form inputs.
   *
   * @type {AccountConfig}
   */
  #currentConfig;

  /**
   * Indicates if the form has been updated by the user.
   *
   * @type {boolean}
   */
  #edited;

  connectedCallback() {
    if (this.hasConnected) {
      return;
    }
    this.hasConnected = true;

    super.connectedCallback();

    const template = document
      .getElementById("accountHubIncomingEmailFormTemplate")
      .content.cloneNode(true);
    this.appendChild(template);

    this.#incomingProtocol = this.querySelector("#incomingProtocol");
    this.#incomingPort = this.querySelector("#incomingPort");
    this.#incomingHostname = this.querySelector("#incomingHostname");
    this.#incomingConnectionSecurity = this.querySelector(
      "#incomingConnectionSecurity"
    );
    this.#incomingAuthenticationMethod = this.querySelector(
      "#incomingAuthMethod"
    );
    this.#incomingUsername = this.querySelector("#incomingUsername");
    this.#incomingExchangeUrl = this.querySelector("#incomingExchangeUrl");
    this.setupEventListeners();
    this.#currentConfig = {};
    this.#edited = false;
  }

  /**
   * Set up the event listeners for this workflow.
   */
  setupEventListeners() {
    this.#incomingHostname.addEventListener("input", () => {
      this.#configChanged();
      this.#adjustOAuth2Visibility();
    });

    this.#incomingUsername.addEventListener("input", () => {
      this.#configChanged();
    });

    this.#incomingAuthenticationMethod.addEventListener("change", () => {
      this.#configChanged();
    });

    this.#incomingConnectionSecurity.addEventListener("change", () => {
      this.#configChanged();
      this.#adjustPortToSSLAndProtocol();
    });
    this.#incomingPort.addEventListener("input", () => {
      this.#configChanged();
      this.#adjustSSLToPort();
    });

    this.#incomingProtocol.addEventListener("change", () => {
      this.#updateConfigInputsVisibility(this.#incomingProtocol.value >= 4);
      this.#configChanged();
      this.#adjustPortToSSLAndProtocol();
      this.#adjustOAuth2Visibility();
    });

    this.#incomingExchangeUrl.addEventListener("input", () => {
      this.#configChanged();
      this.#adjustOAuth2Visibility();
    });

    this.querySelector("#advancedConfigurationIncoming").addEventListener(
      "click",
      this
    );
  }

  handleEvent(event) {
    if (event.target.id === "advancedConfigurationIncoming") {
      this.dispatchEvent(
        new CustomEvent("advanced-config", {
          bubbles: true,
        })
      );
    }
  }

  /**
   * @typedef {object} ConfigFormState
   * @property {AccountConfig} config - The updated AccountConfig.
   * @property {boolean} edited - If form has been edited.
   */

  /**
   * Return the current state of the email setup form, with the updated
   * incoming fields, and a property that tells if the form has been edited.
   *
   * @returns {ConfigFormState} State details.
   */
  captureState() {
    return {
      config: this.getIncomingUserConfig(),
      edited: this.#edited,
    };
  }

  /**
   * Sets the state of the incoming email config state.
   *
   * @param {AccountConfig} configData - Applies the config data to this state.
   */
  setState(configData) {
    this.classList.toggle(
      "stacked",
      Services.prefs.getIntPref("mail.uifontsize") >= 17
    );
    this.#currentConfig = configData;
    this.updateFields(this.#currentConfig);
    this.#checkFormValidity();
  }

  /**
   * Refreshes the edited state of the incoming config.
   */
  resetState() {
    this.#edited = false;
  }

  /**
   * Dispatches an event to the email controller whenever there is a change in
   * configuration with the detail of the incoming config being complete.
   */
  #configChanged() {
    this.#edited = true;
    this.#checkFormValidity();
  }

  #checkFormValidity() {
    let completed = false;
    try {
      const completeConfig =
        this.getIncomingUserConfig().isIncomingEditedComplete();
      const validForm =
        this.querySelector("#incomingEmailForm").checkValidity();
      completed = completeConfig && validForm;
    } catch (error) {
      // We're just trying to get the config values here, so if it fails
      // we can silently fail.
    }

    this.dispatchEvent(
      new CustomEvent("config-updated", {
        bubbles: true,
        detail: { completed },
      })
    );
  }

  /**
   * Make OAuth2 visible as an authentication method when a hostname that
   * OAuth2 can be used with is entered.
   *
   * @param {AccountConfig} [accountConfig] - Complete AccountConfig.
   */
  #adjustOAuth2Visibility(accountConfig) {
    // Get current config.
    const config = accountConfig || this.getIncomingUserConfig();
    let incomingDetails = "";

    // If it's an exchange account and the experimental pref to allow
    // OAuth customization is enabled, always allow OAuth since they
    // will be able to customize the account later.
    const oauthCustomizationEnabled = Services.prefs.getBoolPref(
      "experimental.mail.ews.overrideOAuth.enabled",
      false
    );
    if (oauthCustomizationEnabled && config.isExchangeConfig()) {
      this.querySelector("#incomingAuthMethodOAuth2").hidden = false;
    } else {
      // We get the input value here instead of using the config, because the
      // config isn't updated until the value is valid, which leads to stale
      // data.
      try {
        const host = config.isExchangeConfig()
          ? URL.parse(InputSanitizer.url(this.#incomingExchangeUrl.value))
              ?.hostname
          : InputSanitizer.hostname(this.#incomingHostname.value);

        // If the incoming server hostname supports OAuth2, enable it.
        incomingDetails =
          host &&
          OAuth2Providers.getHostnameDetails(host, config.incoming.type);
      } catch (error) {
        incomingDetails = "";
      }

      this.querySelector("#incomingAuthMethodOAuth2").hidden = !incomingDetails;
      if (incomingDetails) {
        gAccountSetupLogger.debug(
          `OAuth2 details for incoming server ${config.incoming.hostname} is ${incomingDetails}`
        );
      }
    }

    // If OAuth isn't an option, we reset the Authentication option to default,
    // "Normal Password".
    if (
      !(
        (oauthCustomizationEnabled && config.isExchangeConfig()) ||
        incomingDetails
      ) &&
      this.#incomingAuthenticationMethod.value == Ci.nsMsgAuthMethod.OAuth2
    ) {
      this.#incomingAuthenticationMethod.value =
        Ci.nsMsgAuthMethod.passwordCleartext;
      config.incoming.auth = InputSanitizer.integer(
        this.#incomingAuthenticationMethod.value
      );
    }

    this.#currentConfig = config;
  }

  /**
   * Automatically fill port field when connection security has changed in,
   * unless the user entered a non-standard port.
   *
   * @param {AccountConfig} [accountConfig] - Complete AccountConfig.
   */
  #adjustPortToSSLAndProtocol(accountConfig) {
    // Get current config.
    const config = accountConfig || this.getIncomingUserConfig();
    const socketType = config.incoming.socketType;
    const plainSecurity = socketType == Ci.nsMsgSocketType.plain;

    // If connection security chosen is none, show insecure connection warning.
    this.#incomingConnectionSecurity.toggleAttribute("warning", plainSecurity);

    if (config.incoming.port && !standardPorts.includes(config.incoming.port)) {
      return;
    }

    switch (config.incoming.type) {
      case "imap":
        this.#incomingPort.value =
          socketType == Ci.nsMsgSocketType.SSL ? 993 : 143;
        break;

      case "pop3":
        this.#incomingPort.value =
          socketType == Ci.nsMsgSocketType.SSL ? 995 : 110;
        break;

      case "exchange":
        this.#incomingPort.value = 443;
        break;
    }

    config.incoming.port = this.#incomingPort.value;
    this.#currentConfig = config;
  }

  /**
   * If the user changed the port manually, adjust the SSL value,
   * (only) if the new port is impossible with the old SSL value.
   *
   * @param {AccountConfig} [accountConfig] - Complete AccountConfig.
   */
  #adjustSSLToPort(accountConfig) {
    const config = accountConfig || this.getIncomingUserConfig();

    if (!standardPorts.includes(config.incoming.port)) {
      return;
    }

    if (config.incoming.type == "imap") {
      // Implicit TLS for IMAP is on port 993.
      if (
        config.incoming.port == 993 &&
        config.incoming.socketType != Ci.nsMsgSocketType.SSL
      ) {
        this.#incomingConnectionSecurity.value = Ci.nsMsgSocketType.SSL;
      } else if (
        config.incoming.port == 143 &&
        config.incoming.socketType == Ci.nsMsgSocketType.SSL
      ) {
        this.#incomingConnectionSecurity.value =
          Ci.nsMsgSocketType.alwaysSTARTTLS;
      }
    }

    if (config.incoming.type == "pop3") {
      // Implicit TLS for POP3 is on port 995.
      if (
        config.incoming.port == 995 &&
        config.incoming.socketType != Ci.nsMsgSocketType.SSL
      ) {
        this.#incomingConnectionSecurity.value = Ci.nsMsgSocketType.SSL;
      } else if (
        config.incoming.port == 110 &&
        config.incoming.socketType == Ci.nsMsgSocketType.SSL
      ) {
        this.#incomingConnectionSecurity.value =
          Ci.nsMsgSocketType.alwaysSTARTTLS;
      }
    }

    config.incoming.socketType = this.#incomingConnectionSecurity.value;

    this.#currentConfig = config;
  }

  /**
   * Returns an Account Config object with all the sanitized user-inputted
   * data for a manual config email guess attempt.
   *
   * @returns {AccountConfig}
   */
  getIncomingUserConfig() {
    let config = this.#currentConfig.copy();
    config.source = AccountConfig.kSourceUser;

    // Update the type based on the current selection.
    config.incoming.type = InputSanitizer.translate(
      this.#incomingProtocol.value,
      {
        1: "imap",
        2: "pop3",
        3: "exchange",
        4: "ews",
        5: "graph",
        0: null,
      }
    );

    // An EWS configuration won't have any of the default fields available to
    // edit.
    if (config.isExchangeConfig()) {
      config = this.#getExchangeConfigValues(config);
    } else {
      config = this.#getDefaultConfigValues(config);
    }

    config.incoming.auth = InputSanitizer.integer(
      this.#incomingAuthenticationMethod.value
    );
    config.incoming.username = this.#incomingUsername.value;
    !this.#incomingUsername.value
      ? this.#incomingUsername.setAttribute(
          "aria-describedby",
          "incomingUsernameErrorMessage"
        )
      : this.#incomingUsername.removeAttribute("aria-describedby");
    this.#incomingUsername.setAttribute(
      "aria-invalid",
      !this.#incomingUsername.value
    );

    return config;
  }

  /**
   * Updates the fields with the confirmed AccountConfig from
   * guessConfig, called by parent template.
   *
   * @param {AccountConfig} config - The config to present to the user.
   */
  updateFields(config) {
    assert(config instanceof AccountConfig);
    this.#updateConfigInputsVisibility(config.isExchangeConfig());

    this.#incomingProtocol.value = InputSanitizer.translate(
      config.incoming.type,
      { imap: 1, pop3: 2, exchange: 3, ews: 4, graph: 5 },
      1
    );
    this.#incomingHostname.value = config.incoming.hostname;
    this.#incomingConnectionSecurity.value = InputSanitizer.enum(
      config.incoming.socketType,
      [-1, 0, 1, 2, 3],
      0
    );

    // If a port number was specified other than "Auto"
    if (config.incoming.port) {
      this.#incomingPort.value = config.incoming.port;
    } else {
      this.#adjustPortToSSLAndProtocol(config);
    }

    this.#incomingExchangeUrl.value =
      config.incoming.exchangeURL ||
      (config.incoming.hostname &&
        config.incoming.hostname[0] != "." &&
        `https://${config.incoming.hostname}`) ||
      "";

    this.#incomingAuthenticationMethod.value = InputSanitizer.enum(
      config.incoming.auth,
      [0, 3, 4, 5, 6, 10],
      0
    );
    this.#incomingUsername.value = config.incoming.username;

    this.#adjustOAuth2Visibility(config);
  }

  /**
   * Captures and sanitizes the incoming config fields that are for a default
   * incoming configuration (non ews), and then returns the updated config.
   *
   * @param {AccountConfig} config - The current account config.
   * @returns {AccountConfig}
   */
  #getDefaultConfigValues(config) {
    try {
      const inHostnameValue = this.#incomingHostname.value;
      config.incoming.hostname = InputSanitizer.hostname(inHostnameValue);
      this.#incomingHostname.value = config.incoming.hostname;
      this.#incomingHostname.setCustomValidity("");
      this.#incomingHostname.setAttribute("aria-invalid", false);
      this.#incomingHostname.removeAttribute("aria-describedby");
    } catch (error) {
      gAccountSetupLogger.warn(error);
      this.#incomingHostname.setCustomValidity(error._message);
      this.#incomingHostname.setAttribute("aria-invalid", true);
      this.#incomingHostname.setAttribute(
        "aria-describedby",
        "incomingHostnameErrorMessage"
      );
    }

    try {
      config.incoming.port = InputSanitizer.integerRange(
        this.#incomingPort.valueAsNumber,
        1,
        65535
      );
      this.#incomingPort.setCustomValidity("");
      this.#incomingPort.setAttribute("aria-invalid", false);
      this.#incomingPort.removeAttribute("aria-describedby");
    } catch (error) {
      // Include default "Auto".
      config.incoming.port = undefined;
      this.#incomingPort.setCustomValidity(error._message);
      this.#incomingPort.setAttribute("aria-invalid", true);
      this.#incomingPort.setAttribute(
        "aria-describedby",
        "incomingPortErrorMessage"
      );
    }

    config.incoming.socketType = InputSanitizer.integer(
      this.#incomingConnectionSecurity.value
    );

    return config;
  }

  /**
   * Captures and sanitizes the incoming config fields that are for an exchange
   * (configuration), and then returns the updated config.
   *
   * @param {AccountConfig} config - The current account config.
   * @returns {AccountConfig}
   */
  #getExchangeConfigValues(config) {
    // Skip validation while there isn't a URL with a full host in the field
    // to avoid inserting a slash into the host through the validation.
    // Reset the exchange host in case there was a URL with a full host
    // previously and the url was edited.
    if (/^[^/]+\/\/[^/]+$/.test(this.#incomingExchangeUrl.value)) {
      config.incoming.hostname = "";
      return config;
    }

    try {
      const inExchangeUrl = this.#incomingExchangeUrl.value;
      config.incoming.exchangeURL = InputSanitizer.url(inExchangeUrl);
      this.#incomingExchangeUrl.value = config.incoming.exchangeURL;
      this.#incomingExchangeUrl.setCustomValidity("");
      this.#incomingExchangeUrl.setAttribute("aria-invalid", false);
      this.#incomingExchangeUrl.removeAttribute("aria-describedby");

      // For Exchange, the hostname should be set from the Exchange URL.
      const hostname = URL.parse(config.incoming.exchangeURL)?.hostname;
      if (hostname) {
        config.incoming.hostname = hostname;
      }
    } catch (error) {
      gAccountSetupLogger.warn(error);
      config.incoming.hostname = "";
      this.#incomingExchangeUrl.setCustomValidity(error._message);
      this.#incomingExchangeUrl.setAttribute("aria-invalid", true);
      this.#incomingExchangeUrl.setAttribute(
        "aria-describedby",
        "incomingEwsUrlErrorMessage"
      );
    }

    return config;
  }

  /**
   * Shows/Hides the config inputs based on if we're editing an EWS
   * configuration.
   *
   * @param {boolean} isExchange - If the config is an EWS config.
   */
  #updateConfigInputsVisibility(isExchange) {
    const configOptions = {
      "#incomingHostnameFormGroup": isExchange,
      "#incomingExchangeUrlFormGroup": !isExchange,
      "#nonEwsFormRow": isExchange,
      "#incomingAuthMethodAutodetect": isExchange,
      "#incomingAuthMethodEncrypted": isExchange,
      "#incomingAuthMethodKerbos": isExchange,
    };

    for (const [optionID, hide] of Object.entries(configOptions)) {
      const element = this.querySelector(optionID);
      element.hidden = hide;

      for (const input of element.querySelectorAll("input")) {
        if (input.required || input.dataset.wasRequired) {
          input.required = !hide;
          input.dataset.wasRequired = true;
        }
        if (input.validity.customError) {
          input.setCustomValidity("");
        }
        if (input.ariaInvalid) {
          input.ariaInvalid = "false";
        }
      }
    }

    // If we're switching to EWS, make sure a valid authentication method
    // is selected.
    if (
      isExchange &&
      !["3", "6", "10"].includes(this.#incomingAuthenticationMethod.value)
    ) {
      this.#incomingAuthenticationMethod.value = "3";
    }

    // Only check form validity if the user has already interacted with the form.
    if (this.#edited) {
      this.#checkFormValidity();
    }
  }
}

customElements.define("email-manual-incoming-form", EmailIncomingForm);
